"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1499-01-01:0":{"b": ["Dholavira: Awamu ya VII ya Dholavira yamalizika", "87ad0540"], "d": ["Mji wa Harappa wa Kachchh (kisiwa cha Khadir); kulingana na mpangilio wa UNESCO/ASI, ukaaji wa takriban miaka 1.500 wa awamu 7 ulioanza c. 3000 KK; Awamu ya VII (~1500-1450 KK) ni makazi ya mwisho yasiyo na sifa ya mji, baada ya hapo hayakukaliwa kamwe.", "a6493b11"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1499-01-01:1":{"b": ["Mipaka ya nasaba/kipindi cha Shang (mfumo wa Erligang-Yinxu): Kipindi cha Shang chaanza (mfano wa 14C)", "98c7f77f"], "d": ["Thamani mbili za mwanzo wa Shang: ~1500 (Sci Rep 2018, Erligang Zhengzhou) na ~1600 (Mradi wa Vipindi; wimbi la awali, Guangming Daily/Lee 2007). Mwisho: ushindi wa Zhou 1046 (Li 2002) na 14C ~1041.", "271aafb3"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-1999-01-01:0":{"b": ["Lothal: Kudorora kwa Lothal", "42da4755"], "d": ["Mji wa bandari/uzalishaji wa Harappa kwenye pwani ya Gujarat; kulingana na Rao Waharappa walifika hapa c. 2450 KK; tarehe za TF zilizosawazishwa zinaweka awamu ya Harappa Iliyokomaa ~2650-2200 KK, awamu ya Harappa ya Marehemu (B) ~2315-1865 KK.", "b1919748"]},
