"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-2002-01-01:0":{"b": ["Nasaba ya Ur III (Ur): Nasaba ya Ur III yamalizika (mwaka wa mwisho wa Ibbi-Suen)", "ad03c93c"], "d": ["Nasaba ya Ur III iliyoanzishwa na Urnamma iligeuza Mesopotamia ya Kusini kuwa dola ya kitovu wakati wa Şulgi; nasaba inaisha na mfalme wa mwisho Ibbi-Suen.", "79981126"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-2109-01-01:0":{"b": ["Nasaba ya Ur III (Ur): Nasaba ya Ur III: mwaka wa 1 wa Ur-Nammu", "d3b3f3f1"], "d": ["Nasaba ya Ur III iliyoanzishwa na Urnamma iligeuza Mesopotamia ya Kusini kuwa dola ya kitovu wakati wa Şulgi; nasaba inaisha na mfalme wa mwisho Ibbi-Suen.", "79981126"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-2141-01-01:0":{"b": ["Dola ya Akkad (Sargon): Dola ya Akkad: utawala wa mfalme wa mwisho Şudurul wamalizika", "67e506f0"], "d": ["Sargon (Šarru-kīn) kumshinda Lugalzagesi na kuanzisha dola ya kwanza pana ya Mesopotamia yenye kitovu Akkade; kilele wakati wa Naram-Suen; mtawala wa mwisho Shudurul.", "7859346f"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-2323-01-01:0":{"b": ["Dola ya Akkad (Sargon): Dola ya Akkad: Utawala wa Sargon waanza (Kronolojia ya Kati)", "de4a9e87"], "d": ["Sargon (Šarru-kīn) kumshinda Lugalzagesi na kuanzisha dola ya kwanza pana ya Mesopotamia yenye kitovu Akkade; kilele wakati wa Naram-Suen; mtawala wa mwisho Shudurul.", "7859346f"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-3199-01-01:0":{"b": ["Uruk IV–III (kuibuka kwa maandishi): Awamu ya Uruk III yamalizika", "7173d057"], "d": ["Vidonge vya kwanza vya kiutawala vya maandishi-mwanzo ya kikuni kuzunguka Eanna (Uruk IV, kisha Uruk III); mfumo wa kwanza wa maandishi ulioandikwa kwa alama za nambari na za kiishara.", "49513cb9"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-3349-01-01:0":{"b": ["Uruk IV–III (kuibuka kwa maandishi): Awamu ya Uruk IVa: matabaka ambapo maandishi yalijitokeza (Uruk IV–III) yaanza", "18696f9e"], "d": ["Vidonge vya kwanza vya kiutawala vya maandishi-mwanzo ya kikuni kuzunguka Eanna (Uruk IV, kisha Uruk III); mfumo wa kwanza wa maandishi ulioandikwa kwa alama za nambari na za kiishara.", "49513cb9"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-3799-01-01:0":{"b": ["Utamaduni wa Ubaid (Mesopotamia ya kusini): Kipindi cha Ubaid kimalizika (Carter & Philip 2010; Egberts na wengine 2023 wanasema mwisho 4200 KK)", "989b0216"], "d": ["Utamaduni wa vyombo vya udongo vilivyopakwa rangi wa vijiji vya hekalu vya makazi ya awali ulioenea kati ya Ubaid 0 (Oueili) na Ubaid 5 (Terminal) Mesopotamia ya kusini; kipindi cha Uruk kinafuata.", "28d97520"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-5499-01-01:0":{"b": ["Utamaduni wa Halaf: tarehe ya marehemu zaidi ya kipindi cha Halaf (mpaka wa juu)", "60c7d900"], "d": ["Utamaduni wa Neolithic ya Marehemu/Chalcolithic wenye vyombo vya udongo vilivyopakwa rangi vizuri huko Mesopotamia ya Kaskazini (unaoanza kwa mpito hadi Halaf ya Mapema katika mfululizo wa Tell Sabi Abyad); kwa athari ya Ubaid unaachia nafasi kwa Ubaid ya Kaskazini.", "1f8017e6"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-5899-01-01:0":{"b": ["Utamaduni wa Halaf: Utamaduni wa Halaf: kupanda kwaanza (ncha ya mapema zaidi yenye tarehe)", "6ea5ce60"], "d": ["Utamaduni wa Neolithic ya Marehemu/Chalcolithic wenye vyombo vya udongo vilivyopakwa rangi vizuri huko Mesopotamia ya Kaskazini (unaoanza kwa mpito hadi Halaf ya Mapema katika mfululizo wa Tell Sabi Abyad); kwa athari ya Ubaid unaachia nafasi kwa Ubaid ya Kaskazini.", "1f8017e6"]},
"OLAYLAR_ARKEOLOJI_MEZOPOTAMYA:-6499-01-01:0":{"b": ["Utamaduni wa Ubaid (Mesopotamia ya kusini): Utamaduni wa Ubaid: awamu ya kwanza yenye tarehe ya Ubaid Mesopotamia ya kusini yaanza", "25202952"], "d": ["Utamaduni wa vyombo vya udongo vilivyopakwa rangi wa vijiji vya hekalu vya makazi ya awali ulioenea kati ya Ubaid 0 (Oueili) na Ubaid 5 (Terminal) Mesopotamia ya kusini; kipindi cha Uruk kinafuata.", "28d97520"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-0299-01-01:0":{"b": ["Ufalme wa Kush — kipindi cha Meroe: kinaanza", "ee436c47"], "d": ["Kipindi cha Meroe kinachoanza kwa kuhamia kwa kitovu cha Kush kutoka Napata hadi Meroe (karibu 300 KK) na kinachoenea hadi BK 350.", "5c13abcf"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1069-01-01:0":{"b": ["Ufalme wa Kush — kipindi cha Napata: kinaanza", "fd21e916"], "d": ["Kipindi cha nasaba ya Kush chenye kitovu Napata; kitovu kinahamia Meroe ~300 KK. Nasaba ya XXV (Kush) iliyoiteka Misri inatokea katika kipindi hiki — tarehe za Nasaba ya XXV HAZIPO katika chanzo hiki.", "b8938f36"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1449-01-01:0":{"b": ["Ufalme/utamaduni wa Kerma (Kush): wamalizika", "95c2812c"], "d": ["Ufalme wa Nubia wenye kitovu Kerma chini ya Maporomoko ya Tatu; ukipita awamu za Kerma ya Kale (~2500), ya Kati, ya Kawaida, unaisha ~1450 KK. Honegger 2005: 'Kerma Classique (vers 1500 av. J.-C.)' makazi yaliyozingirwa.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1499-01-01:0":{"b": ["Napata (Cebel Barkal): yaanza", "fbf16715"], "d": ["Ilianzishwa kama kituo chenye ngome cha Misri katika Ufalme Mpya; mji mkuu wa nasaba ya Kush (kipindi cha Napata 1070–300 KK), ilihifadhi umuhimu wake katika kipindi cha Meroe (300 KK–BK 350).", "a384d267"]},
