"OLAYLAR_ARKEOLOJI_ZINCIR:-1464-01-01:0":{"b": ["Uruk, Ur: pengo lisilo na mmiliki → Ufalme wa Babeli ya Kassite", "691f41a8"], "d": ["Katika sehemu za Uruk, Ur umiliki hupita kutoka pengo lisilo na mmiliki hadi Ufalme wa Babeli ya Kassite. Taarifa ya chanzo cha mpito: Nchi ya Bahari inaunganishwa na Babeli (ca. 1465; Brinkman 1972, Edens 1994) | Chanzo: Zadok, R., \"Kassites\", Encyclopaedia Iranica XVI/2, 2013, uk. 113-118 (rev. 2015); kronolojia Boese 1982 / Brinkman 1986 | https://web.archive.org/web/2025/https://www.iranicaonline.org/articles/kassites | «was incorporated into Babylonia in ca. 1465 BCE»", "1f9c242d"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-1474-01-01:0":{"b": ["Uruk: Nasaba ya Kwanza ya Nchi ya Bahari → pengo lisilo na mmiliki", "a824108a"], "d": ["Katika sehemu za Uruk umiliki hupita kutoka Nasaba ya Kwanza ya Nchi ya Bahari hadi pengo lisilo na mmiliki. Taarifa ya chanzo cha mpito: Karne ya 16 KK: Babeli inagawanywa mara mbili - kaskazini Wakassite, kusini Nchi ya Bahari inayojumuisha Uruk, Ur na Larsa | Chanzo: Zadok, R., \"Kassites\", Encyclopaedia Iranica XVI/2, 2013, uk. 113-118 (rev. 2015); kronolojia Boese 1982 / Brinkman 1986 | https://web.archive.org/web/2025/https://www.iranicaonline.org/articles/kassites | «Babylonia was divided into two kingdoms, that of the Kassites in the north and the Sealand in the south, including Uruk, Ur, and Larsa»", "918eed44"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-1499-01-01:0":{"b": ["Kerma (Kerma / Doukki Gel): Ufalme wa Kerma (Kerma ya Kawaida) → pengo lisilo na mmiliki", "c07aa694"], "d": ["Katika sehemu za Kerma (Kerma / Doukki Gel) umiliki hupita kutoka Ufalme wa Kerma (Kerma ya Kawaida) hadi pengo lisilo na mmiliki. Taarifa ya chanzo cha mpito: Kerma.ch: Kerma ya Mapema 2450-2050 \"City founded\"; Kati 2050-1750; ya Kawaida 1750-1480", "849609b2"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-1731-01-01:0":{"b": ["Uruk: pengo lisilo na mmiliki → Nasaba ya Kwanza ya Nchi ya Bahari", "f7f634c0"], "d": ["Katika sehemu za Uruk umiliki hupita kutoka pengo lisilo na mmiliki hadi Nasaba ya Kwanza ya Nchi ya Bahari. Taarifa ya chanzo cha mpito: Karne ya 16 KK: Babeli inagawanywa mara mbili - kaskazini Wakassite, kusini Nchi ya Bahari inayojumuisha Uruk, Ur na Larsa | Chanzo: Zadok, R., \"Kassites\", Encyclopaedia Iranica XVI/2, 2013, uk. 113-118 (rev. 2015); kronolojia Boese 1982 / Brinkman 1986 | https://web.archive.org/web/2025/https://www.iranicaonline.org/articles/kassites | «Babylonia was divided into two kingdoms, that of the Kassites in the north and the Sealand in the south, including Uruk, Ur, and Larsa»", "68e524be"]},
